        var http = (httpMethod ?? string.Empty).Trim();
        var path = (urlPath ?? string.Empty).Split('?')[0].TrimEnd('/');
        var model = (modelName ?? string.Empty).Trim();
        var dtoSingular = Singularize(model) + "Dto";

