        if (http.Equals("Put", StringComparison.OrdinalIgnoreCase)
            || http.Equals("Delete", StringComparison.OrdinalIgnoreCase)
            || http.Equals("Patch", StringComparison.OrdinalIgnoreCase))
            return ("bool", ScalarJson("bool", "Raw JSON boolean body (not an object). Example: true"));

        if (ContainsExists(path, methodName))
            return ("bool", ScalarJson("bool", "Raw JSON boolean — whether a matching record exists. Example: true"));

        var segs = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
        var resource = segs.Length > 2 ? segs[2] : string.Empty;
        var last = segs.Length > 0 ? segs[^1] : string.Empty;
        var lastClean = last.Split('{')[0].TrimEnd('-');

        if (last.Contains('{', StringComparison.Ordinal))
            return FromDtoType(dtoSingular, wrapList: false);

        if (http.Equals("Post", StringComparison.OrdinalIgnoreCase)
            && (string.Equals(lastClean, resource, StringComparison.OrdinalIgnoreCase)
                || string.Equals(methodName, "Post", StringComparison.OrdinalIgnoreCase)
                || string.Equals(methodName, "Insert", StringComparison.OrdinalIgnoreCase)))
            return FromDtoType(dtoSingular, wrapList: false);

        // Filter / custom GET: /api/{module}/{resource}/{filter}
