            if (filterPascal.StartsWith("Exists", StringComparison.OrdinalIgnoreCase)
                || filterPascal.Contains("IsExists", StringComparison.OrdinalIgnoreCase))
                return ("bool", ScalarJson("bool", "Raw JSON boolean — whether a matching record exists. Example: true"));

            var responseDto = filterPascal + "ResponseDto";
            if (TypeIndex.Value.ContainsKey(responseDto))
                return FromDtoType(responseDto, wrapList: true);

            return FromDtoType(dtoSingular, wrapList: true);
