        if (http.Equals("Get", StringComparison.OrdinalIgnoreCase))
            return FromDtoType(dtoSingular, wrapList: true);

        if (http.Equals("Post", StringComparison.OrdinalIgnoreCase))
            return FromDtoType(dtoSingular, wrapList: false);

        return FromDtoType(dtoSingular, wrapList: true);
