            .Where(p => p.CanRead && p.GetIndexParameters().Length == 0)
            .Where(p => !string.Equals(p.Name, "EqualityContract", StringComparison.Ordinal))
            .Select(p => new FieldSchema(
                GetJsonName(p),
                FormatTypeName(p.PropertyType),
