    private sealed record FieldSchema(string name, string type, string description);

    private static Dictionary<string, Type> BuildTypeIndex()
    {
        var map = new Dictionary<string, Type>(StringComparer.OrdinalIgnoreCase);
        // All module NSwag contracts live in the Integration assembly referenced by Portal.
        var asm = typeof(ApiModulePermissions).Assembly;

        Type[] types;
        try
        {
            types = asm.GetTypes();
        }
        catch (ReflectionTypeLoadException ex)
        {
            types = ex.Types.Where(t => t != null).Cast<Type>().ToArray();
