                var newIsResponse = type.Name.EndsWith("ResponseDto", StringComparison.Ordinal);
                if (existingIsResponse || !newIsResponse)
                    continue;
            }

            map[type.Name] = type;
        }

        return map;
    }

    private static bool ContainsExists(string path, string methodName)
    {
        var p = path ?? string.Empty;
        var m = methodName ?? string.Empty;
