               || p.Contains("is-exists", StringComparison.OrdinalIgnoreCase)
               || m.Contains("IsExists", StringComparison.OrdinalIgnoreCase)
               || m.StartsWith("Exists", StringComparison.OrdinalIgnoreCase);
